// Giữ nguyên các màu sắc đã định nghĩa
val Background = Brush.verticalGradient(listOf(
    Color(0xFF2E3A4A),
    Color(0xFF28323E),
    Color(0xFF222933)
))
val TextGrey = Color(0xFF9AA3AE)
val GreenGift = Color(0xFF7CB342)
val StarYellow = Color(0xFFFFC107)
val RatingBarBg = Color(0xFF2B323D)

@Composable
fun SelfHelpScreen(navController: NavController) {

    // 1. Thêm State để lưu trạng thái View (Grid hay List)
    var isGridView by remember { mutableStateOf(false) }

    val books: List<Book> = remember {
        SampleData.healingBooks + SampleData.popularBooks + SampleData.popularBooks
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(brush = Background)
            .statusBarsPadding()
    ) {
        // --- Header (Giữ nguyên) ---
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 8.dp, vertical = 8.dp)
        ) {
            IconButton(
                onClick = { navController.popBackStack() },
                modifier = Modifier
                    .background(Color.White.copy(alpha = 0.1f), shape = CircleShape)
                    .size(40.dp)
            ) {
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                    contentDescription = "Back",
                    tint = Color.White,
                    modifier = Modifier.size(20.dp)
                )
            }
            Spacer(modifier = Modifier.height(16.dp))
            Text(
                text = "Sách Self-Help",
                color = Color.White,
                fontSize = 28.sp,
                fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(horizontal = 8.dp)
            )
        }

        Spacer(modifier = Modifier.height(16.dp))

        // --- Container Nội dung ---
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .fillMaxHeight()
                .clip(RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp))
                .background(Color(0xFF1B1C20))
        ) {
            Column {
                Spacer(modifier = Modifier.height(8.dp))

                // 2. Section "Tất cả sách" + Icon Switcher
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 12.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "Tất cả sách",
                        color = TextGrey,
                        fontSize = 16.sp
                    )

                    // Nút chuyển đổi View
                    IconButton(onClick = { isGridView = !isGridView }) {
                        Icon(
                            // Logic đổi Icon: Đang Grid thì hiện List, đang List thì hiện Grid
                            imageVector = if (isGridView) Icons.AutoMirrored.Filled.List else Icons.Filled.GridView,
                            contentDescription = "Switch View",
                            tint = TextGrey,
                            modifier = Modifier.size(24.dp)
                        )
                    }
                }

                // 3. Hiển thị nội dung dựa theo state isGridView
                if (isGridView) {
                    // --- GRID VIEW ---
                    LazyVerticalGrid(
                        columns = GridCells.Fixed(2), // 2 Cột
                        contentPadding = PaddingValues(16.dp),
                        horizontalArrangement = Arrangement.spacedBy(16.dp), // Khoảng cách ngang
                        verticalArrangement = Arrangement.spacedBy(24.dp)   // Khoảng cách dọc
                    ) {
                        items(books) { book ->
                            BookGridItem(
                                title = book.title,
                                author = book.author,
                                coverUrl = book.coverUrl.toString(),
                                rating = book.rating,
                                reviewCount = 104,
                                onClick = {
                                    navController.navigate("audio_player/${book.id}")
                                }
                            )
                        }
                    }
                } else {
                    // --- LIST VIEW (Code cũ) ---
                    LazyColumn(
                        contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp)
                    ) {
                        items(books) { book ->
                            BookListItem(
                                title = book.title,
                                author = book.author,
